    reportError: (error: unknown, fallbackMessage: string) => void
    scheduleCommit: (file: MarkdownFile, message: string) => void
    subscribeRunEvents: (listener: (event: ActionRunEvent) => void) => () => void
}

const INITIAL_SNAPSHOT: DiagramViewSnapshot = {
    currentDiagram: null,
    currentDiagramError: null,
    error: null,
    index: emptyDiagramIndex(),
    legend: { collapsed: false, position: null },
    menu: null,
    popup: null,
    status: 'idle',
}

function normalizeSlashes(path: string) {
    return path.replace(/\\/gu, '/')
}

function errorMessage(error: unknown) {
    return error instanceof Error ? error.message : String(error)
}

function defaultDependencies(): DiagramViewDependencies {
    return {
        createId: generateUuid,
        createTimestamp: () => new Date().toISOString(),
        flushCommits: () => dataService.cards.flushPendingCommits(),
        loadActions: () => actionService.getActions(),
        reportError: (error, fallbackMessage) => dialogService.error(error, { fallbackMessage }),
        scheduleCommit: (file, message) => dataService.scheduleFileCommit(file, message),
        subscribeRunEvents: (listener) => actionRunRegistry.subscribeActiveRunEvents(listener),
    }
}

function validateDiagramPaths(index: DiagramIndex, diagramsFolder: string) {
    const outside = Object.values(index.diagrams).find(({ path }) => !isPathInsideDiagramsFolder(path, diagramsFolder))
    if (outside) throw new Error(`Diagram path must stay inside configured diagrams folder: ${outside.path}`)
    const wrongFormat = Object.values(index.diagrams).find(({ path }) => !isDiagramDataPath(path))
    if (wrongFormat) throw new Error(`Diagram path must identify a JSON file: ${wrongFormat.path}`)
}

async function loadDiagram(binding: DiagramProjectBinding, path: string) {
    if (!binding.storage.loadTextFile) throw new Error('Repository text file loading is not available')
    const file = await binding.storage.loadTextFile(binding.project, path)
    const diagram = parseDiagramData(file.content)

    return { diagram, positionedDiagram: layout(diagram) }
}

async function loadActiveDiagram(binding: DiagramProjectBinding, index: DiagramIndex) {
    const diagramId = index.activePath.at(-1)
    if (!diagramId) return { currentDiagram: null, currentDiagramError: null, sourceSnapshot: null }
    try {
        const record = index.diagrams[diagramId]
        const { diagram, positionedDiagram } = await loadDiagram(binding, record.path)

        return {
            currentDiagram: positionedDiagram,
            currentDiagramError: null,
            sourceSnapshot: { diagram, record },
        }
    } catch (error) {
        return { currentDiagram: null, currentDiagramError: errorMessage(error), sourceSnapshot: null }

import { describe, expect, it, vi } from 'vitest'
import type { DiagramData } from './diagram_data'
import type { DiagramRecord } from './diagram_index'
import { DiagramEditSessionService } from './diagram_edit_session_service'
import type { DiagramViewSourceSnapshot } from './diagram_view_service'

const diagram: DiagramData = {
    edges: [{ from: 'orders', id: 'orders-store', kind: 'connection', to: 'store' }],
    groups: [],
    meta: { description: 'Orders architecture', title: 'Overview', type: 'architecture', version: 1 },
    nodes: [
        { id: 'orders', label: 'Orders', role: 'focal' },
        { id: 'store', label: 'Store', role: 'store' },
    ],
}
const firstRecord: DiagramRecord = { actionId: 'overview', id: 'diagram-1', label: 'Overview', path: 'design/diagrams/overview.json' }
const project = { branch: 'main', id: 'project', rootPath: 'C:/repo' }

class DiagramSourceStub extends EventTarget {
    private source: DiagramViewSourceSnapshot | null = null

    getSourceSnapshot = () => this.source

    subscribeSource = (listener: () => void) => {
        this.addEventListener('sourceChanged', listener)

        return () => this.removeEventListener('sourceChanged', listener)
    }

    setSource(source: DiagramViewSourceSnapshot | null) {
        this.source = source
        this.dispatchEvent(new Event('sourceChanged'))
    }
}

function createHarness() {
    const sourceService = new DiagramSourceStub()
    const service = new DiagramEditSessionService(sourceService)
    sourceService.setSource({ diagram, record: firstRecord })
    service.bindProject(project)

    return { service, sourceService }
}

describe('DiagramEditSessionService', () => {
    it('starts with immutable source references and one deep editable copy', () => {
        const { service } = createHarness()

        service.start()
        const original = service.getOriginalDiagramSnapshot()
        const editable = service.getEditableDiagramSnapshot()

        expect(original).toEqual({ diagram, record: firstRecord })
        expect(original?.diagram).toBe(diagram)
        expect(original?.record).toBe(firstRecord)
        expect(editable).toEqual(diagram)
        expect(editable).not.toBe(diagram)
        expect(editable?.nodes).not.toBe(diagram.nodes)

        editable!.nodes[0].label = 'Edited orders'
        expect(diagram.nodes[0].label).toBe('Orders')
        expect(original?.diagram.nodes[0].label).toBe('Orders')
        expect(service.getDirtySnapshot()).toBe(false)
    })

    it('exposes stable snapshots and notifies only changed values', () => {
        const { service } = createHarness()
        const dirtyListener = vi.fn()
        const editableListener = vi.fn()
        const originalListener = vi.fn()
        const sessionListener = vi.fn()
        service.subscribeDirty(dirtyListener)
        service.subscribeEditableDiagram(editableListener)
        service.subscribeOriginalDiagram(originalListener)
        service.subscribeSession(sessionListener)

        service.start()
        const editable = service.getEditableDiagramSnapshot()
        const original = service.getOriginalDiagramSnapshot()
        const session = service.getSessionSnapshot()

